<script setup lang="ts">import {ref,computed,onMounted,onUnmounted,watch} from 'vue';import {route} from '../router';import {plans} from '../stores/plans';import {cases} from '../stores/cases';import {canWrite} from '../stores/auth';import {useTask} from '../hooks/useTask';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';import EmptyState from '../components/common/EmptyState.vue';import StatusPill from '../components/common/StatusPill.vue';import PlanNode from '../components/PlanNode.vue';import {fixed} from '../utils/format';const selected=ref(route.value.query.get('plan')||'demo-plan'),caseId=ref(route.value.query.get('case')||'demo-case'),budget=ref(3),costInputs=ref<Record<string,number>>({}),notice=ref('');const {error,busy,act}=useTask();watch(()=>route.value.query.get('plan'),v=>selected.value=v||'demo-plan');let timer:ReturnType<typeof setInterval>;onMounted(()=>{plans.load();cases.load();timer=setInterval(plans.load,2000)});onUnmounted(()=>clearInterval(timer));const plan=computed(()=>plans.items.value.find(p=>p.id===selected.value)),result=computed(()=>plan.value?.result),currentCase=computed(()=>cases.items.value.find(c=>c.id===caseId.value)||cases.items.value[0]),candidates=computed<string[]>(()=>currentCase.value?.candidates||[]),labels=computed(()=>Object.fromEntries((result.value?.snapshot.nodes||[]).map((n:any)=>[n.node_id,n.label])));watch(candidates,list=>{for(const c of list)if(costInputs.value[c]===undefined)costInputs.value[c]=1},{immediate:true});function submit(){act(async()=>{const costs:Record<string,number>={};for(const c of candidates.value)costs[c]=Number(costInputs.value[c]??1);const p=await plans.create({case_id:currentCase.value.id,budget:Number(budget.value),costs_json:JSON.stringify(costs)});selected.value=p.id;notice.value='观测计划已排队，worker将按新成本规则重算自适应路径，旧计划保持不变。'})}function refill(){if(!plan.value?.snapshot)return;caseId.value=plan.value.case_id;budget.value=plan.value.snapshot.budget;costInputs.value={...plan.value.snapshot.costs};notice.value='已把该计划的成本规则填入表单；修改后保存即生成新计划，旧计划与概率版本不变。'}</script><template><PageHeading index="05 / 观测计划" title="预算内的自适应观测，随每次结果重选下一项。" note="正整数成本与总预算随计划锁定；目标为期望剩余熵最低，允许提前结束，每条路径不重复观测且不超支。成本规则更新后保存即重算新计划，旧计划与案例绑定的概率版本保持不变。"/><Notice :message="error||plans.error.value"/><div class="two-col"><section><div class="run-toolbar"><label>计划记录<select v-model="selected"><option v-for="p in plans.items.value" :key="p.id" :value="p.id">{{p.id==='demo-plan'?'CY-07 预算观测计划':p.id.slice(0,8)}} · {{p.status}}</option></select></label><StatusPill v-if="plan" :status="plan.status"/></div><Notice v-if="plan?.status==='failed'" :message="plan.error"/><EmptyState v-if="plan&&['queued','running'].includes(plan.status)" text="Redis worker正在按预算展开自适应观测树，每两秒刷新。"/><template v-if="plan?.status==='completed'&&result"><section class="plan-summary"><p class="eyebrow">ADAPTIVE PLAN / EXPECTED REMAINING ENTROPY</p><h2>{{result.case_name}} · 总预算 {{result.snapshot.budget}}</h2><div class="probability-summary"><div><small>基准熵 H(Q|E)</small><strong>{{fixed(result.analysis.baseline_entropy,6)}} <em>bit</em></strong><span>不观测即停止时的剩余熵</span></div><div><small>计划期望剩余熵</small><strong>{{fixed(result.analysis.expected_remaining_entropy,6)}} <em>bit</em></strong><span>沿最优自适应策略的期望终点熵</span></div><div><small>期望下降</small><strong>{{fixed(result.analysis.expected_entropy_reduction,6)}} <em>bit</em></strong><span>评估状态 {{result.analysis.evaluated_state_count}} · 计划树节点 {{result.analysis.tree_node_count}}</span></div></div><p class="cost-rule">成本规则：<span v-for="(c,n) in result.snapshot.costs" :key="n" class="cost-chip">{{labels[n]||n}} ×{{c}}</span></p><p class="version-note">{{result.network_name}} / CPT {{result.version}} / {{result.case_name}} · 概率版本随案例锁定</p><p class="hash-note">输入SHA256 {{result.input_sha256}}</p><div class="actions"><button v-if="canWrite()" type="button" class="secondary" @click="refill">沿用此成本规则重算新计划</button></div></section><section class="plan-tree"><p class="eyebrow">DECISION TREE / BRANCH PROBABILITY · CUMULATIVE COST · POSTERIOR</p><PlanNode :node="result.analysis.tree" :target="result.snapshot.target" :labels="labels"/></section><p class="method-note">{{result.analysis.note}}<br>{{result.assumptions}}</p></template></section><form v-if="canWrite()" class="editor-panel" @submit.prevent="submit"><h2>新建观测计划</h2><label>证据案例<select v-model="caseId"><option v-for="c in cases.items.value" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>总预算（非负整数）<input v-model.number="budget" type="number" min="0" step="1" required></label><label v-for="c in candidates" :key="c">观测 {{c}} 的成本（正整数）<input v-model.number="costInputs[c]" type="number" min="1" step="1" :placeholder="'1'" required></label><p v-if="!candidates.length" class="empty">该案例没有未观测的非目标候选，计划将立即结束。</p><button :disabled="busy||!currentCase">保存并重算观测计划</button><p class="success" v-if="notice">{{notice}}</p></form></div></template>
